import sys

def lcs_length(s1: str, s2: str) -> int:
    if not s1 or not s2:
        return 0
    if len(s1) > len(s2):
        s1, s2 = s2, s1
    # Bit-parallel LCS (Allison-Dix / Hyyrö algorithm)
    masks = {}
    for i, ch in enumerate(s1):
        masks[ch] = masks.get(ch, 0) | (1 << i)

    S = (1 << len(s1)) - 1
    mask_all = S
    get = masks.get
    for ch in s2:
        PM = get(ch, 0)
        u = S & PM
        S = (S + u) | (S - u)
    # Count 0 bits in lowest len(s1) bits of S
    return len(s1) - (S & mask_all).bit_count()

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        s1 = lines[0] if lines else ""
        s2 = ""
    else:
        s1, s2 = lines[0], lines[1]
    print(lcs_length(s1, s2))

if __name__ == "__main__":
    main()

#include <stdint.h>
#include <string.h>
#include <stdlib.h>

int lcs_ascii(const uint8_t *s1, int n1, const uint8_t *s2, int n2) {
    if (n1 == 0 || n2 == 0) return 0;

    // Trim common prefix
    int start = 0;
    int min_n = n1 < n2 ? n1 : n2;
    while (start < min_n && s1[start] == s2[start]) {
        start++;
    }
    s1 += start;
    s2 += start;
    n1 -= start;
    n2 -= start;

    // Trim common suffix
    while (n1 > 0 && n2 > 0 && s1[n1 - 1] == s2[n2 - 1]) {
        n1--;
        n2--;
    }

    if (n1 == 0 || n2 == 0) return start;

    if (n1 > n2) {
        const uint8_t *tmp_s = s1; s1 = s2; s2 = tmp_s;
        int tmp_n = n1; n1 = n2; n2 = tmp_n;
    }

    int words = (n1 + 63) >> 6;
    uint64_t stack_pm[256 * 48];
    uint64_t stack_s[48];
    uint64_t *pm = (words <= 48) ? stack_pm : (uint64_t *)calloc(256 * words, sizeof(uint64_t));
    uint64_t *S = (words <= 48) ? stack_s : (uint64_t *)malloc(words * sizeof(uint64_t));

    if (words <= 48) {
        memset(pm, 0, 256 * words * sizeof(uint64_t));
    }

    for (int i = 0; i < n1; i++) {
        pm[(int)s1[i] * words + (i >> 6)] |= (1ULL << (i & 63));
    }

    for (int w = 0; w < words; w++) {
        S[w] = ~0ULL;
    }

    if (words == 1) {
        uint64_t s0 = ~0ULL;
        for (int j = 0; j < n2; j++) {
            uint64_t u = s0 & pm[s2[j]];
            s0 = (s0 + u) | (s0 ^ u);
        }
        uint64_t mask = (n1 == 64) ? ~0ULL : ((1ULL << n1) - 1ULL);
        int zeros = n1 - __builtin_popcountll(s0 & mask);
        return start + zeros;
    }

    for (int j = 0; j < n2; j++) {
        const uint64_t *pm_row = pm + (int)s2[j] * words;
        uint64_t carry = 0;
        for (int w = 0; w < words; w++) {
            uint64_t sw = S[w];
            uint64_t u = sw & pm_row[w];
            __uint128_t sum = (__uint128_t)sw + u + carry;
            carry = (uint64_t)(sum >> 64);
            S[w] = (uint64_t)sum | (sw ^ u);
        }
    }

    int ones = 0;
    for (int w = 0; w < words - 1; w++) {
        ones += __builtin_popcountll(S[w]);
    }
    int rem = n1 & 63;
    uint64_t last_mask = (rem == 0) ? ~0ULL : ((1ULL << rem) - 1ULL);
    ones += __builtin_popcountll(S[words - 1] & last_mask);

    if (words > 48) {
        free(pm);
        free(S);
    }

    return start + (n1 - ones);
}

import ctypes
import os
import sys

_lib = None
try:
    _so_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "_lcs.so")
    if os.path.exists(_so_path):
        _lib = ctypes.CDLL(_so_path)
        _lib.lcs_ascii.argtypes = [ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_int]
        _lib.lcs_ascii.restype = ctypes.c_int
except Exception:
    _lib = None


def _lcs_py(s1: str, s2: str) -> int:
    if not s1 or not s2:
        return 0
    if s1 == s2:
        return len(s1)

    n1, n2 = len(s1), len(s2)
    # Trim common prefix
    start = 0
    min_n = n1 if n1 < n2 else n2
    while start < min_n and s1[start] == s2[start]:
        start += 1

    # Trim common suffix
    end1, end2 = n1, n2
    while end1 > start and end2 > start and s1[end1 - 1] == s2[end2 - 1]:
        end1 -= 1
        end2 -= 1

    if start > 0 or end1 < n1 or end2 < n2:
        s1 = s1[start:end1]
        s2 = s2[start:end2]
        if not s1 or not s2:
            return start + (n1 - end1)

    if len(s1) > len(s2):
        s1, s2 = s2, s1

    m = len(s1)
    masks = {}
    find = s1.find
    for ch in set(s1) & set(s2):
        mask = 0
        pos = find(ch)
        while pos != -1:
            mask |= 1 << pos
            pos = find(ch, pos + 1)
        masks[ch] = mask

    S = (1 << m) - 1
    mask_all = S
    get = masks.get
    for ch in s2:
        PM = get(ch, 0)
        if PM:
            u = S & PM
            S = (S + u) | (S - u)

    return start + (n1 - end1) + (m - (S & mask_all).bit_count())


